import {readFileSync,writeFileSync,readdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
// Build identity covers all local executable modules, workers and application
// markup/styles. Never omit a new controller or snapshot adapter by forgetting
// to append it to a hand-maintained physics list. Exclude this generated file
// itself to avoid a circular digest. Media keep their separate asset manifests.
const dist=new URL('../dist/',import.meta.url);
function sources(directory=dist,prefix=''){
  return readdirSync(directory,{withFileTypes:true}).flatMap(entry=>{
    const name=prefix+entry.name;
    if(entry.isDirectory())return sources(new URL(entry.name+'/',directory),name+'/');
    return name!=='model-build.js'&&/\.(js|html|css)$/.test(name)?[name]:[];
  });
}
const names=sources().sort();
const hashes=Object.fromEntries(names.map(name=>[name,createHash('sha256').update(readFileSync(new URL('../dist/'+name,import.meta.url))).digest('hex')]));
const id=createHash('sha256').update(JSON.stringify(hashes)).digest('hex');
writeFileSync(new URL('../dist/model-build.js',import.meta.url),'// Generated by scripts/model-build.mjs; hashes identify source files, not vehicle validity.\nexport const MODEL_BUILD_ID='+JSON.stringify(id)+';\nexport const MODEL_SOURCE_HASHES='+JSON.stringify(hashes,null,2)+';\n');
console.log('Model build '+id);
